parameters.jsCode:
const original = $('Set - Normalizar datos del mensaje').item.json;
const sesion = $input.item.json || {};

return [{
  json: {
    telefono: original.telefono,
    nombre_whatsapp: original.nombre_whatsapp,
    texto: original.texto,
    texto_normalizado: original.texto_normalizado,
    etapa: sesion.Etapa || 'inicio',
    nombre: sesion.Nombre || '',
    interes: sesion.Interes || '',
    presupuesto: sesion.Presupuesto || '',
    distrito: sesion.Distrito || ''
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "intencion": {
      "type": "string",
      "enum": ["comprar", "alquilar", "asesor", "otro"],
      "description": "Qué quiere hacer el cliente según su mensaje"
    }
  },
  "required": ["intencion"]
}

parameters.jsCode:
const datos = $('Code - Fusionar sesión (o iniciar una nueva)').item.json;
const clasificacion = $input.item.json.output || $input.item.json;

return [{
  json: {
    ...datos,
    intencion: (clasificacion.intencion || 'otro').toLowerCase()
  }
}];

